import React from 'react';
import { NavLink } from 'react-router-dom';
import '../styles/main.css';

const portfolioData = [
  {
    title: "Project One",
    description: "Short description of project one.",
    image: "https://via.placeholder.com/300x200"
  },
  {
    title: "Project Two",
    description: "Short description of project two.",
    image: "https://via.placeholder.com/300x200"
  }
  // Add more projects as needed
];

function Header() {
  return (
    <div>
      {/* Hero Section */}
      <header>
        <div className="container">
          <h1>Adigun Sheriff</h1>
          <p className="welcome-message">Frontend Developer | Designer</p>
          <div>
            {/* Social Links */}
            <NavLink to="/github" target="_blank" rel="noopener noreferrer">GitHub</NavLink> | 
            <NavLink to="/linkedin" target="_blank" rel="noopener noreferrer">LinkedIn</NavLink>
          </div>
        </div>
      </header>

      {/* About Section */}
      <section className="container" style={{ marginTop: 40 }}>
        <h2>About Me</h2>
        <p>
          Write a short bio about yourself here. Highlight your skills, experience, and interests.
        </p>
      </section>

      {/* Portfolio Section */}
      <section className="container" style={{ marginTop: 40 }}>
        <h2>Projects</h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
          {portfolioData.map((item, idx) => (
            <PortfolioItem key={idx} {...item} />
          ))}
        </div>
      </section>

      {/* Contact Section */}
      <section className="container" style={{ marginTop: 40 }}>
        <h2>Contact</h2>
        <p>
          Email: <a href="mailto:your.email@example.com">your.email@example.com</a>
        </p>
      </section>

      {/* Footer */}
      <footer>
        <div className="container">
          &copy; {new Date().getFullYear()} Your Name. All rights reserved.
        </div>
      </footer>
    </div>
  );
}

export default App;
